[3374] = { en = "The Essence of Eranikus", tier = 4,
  t = "De essentie van Eranikus",
  d = "Je gebruikt de Oathstone, en Itharius spreekt via de steen direct tot je geest.$B$B\"Als je de taak in deze Oathstone aanneemt, beloof je mijn doel te steunen, en het doel van Ysera's Dragonflight: de verdorven ziel van Eranikus verlossen. Het eerste offer, een van de vele die jij en ik ongetwijfeld zullen brengen, is dat je mij de edelsteen geeft. Die steen houdt het deel van Eranikus' geest gevangen dat nog een vrije wil heeft.\"$B$B\"Doe dit, $N, en samen verlossen we een ziel die het verdient om verlost te worden.\"",
  o = "Breng de Oathstone of Ysera's Dragonflight en de Chained Essence of Eranikus naar Itharius in de Swamp of Sorrows. Daar maak je je keuze: help je Ysera's Dragonflight of niet.",
  p = "Hier staan we, $N, opnieuw op een kruispunt. Het is tijd voor een nieuwe keuze. Wat kies je, sterveling?",
  c = "Je hebt je keuze gemaakt, en zo begint het. Je keuzes waren tot nu toe wat ik de juiste zou noemen. Je daden vanaf nu bepalen of dat zo blijft.",
