},

[3512] = { en = "In Eranikus' Own Words", tier = 4,
  t = "In Eranikus' eigen woorden",
  d = "$N, onze eerste stap is een manier bedenken om via de edelsteen met Eranikus te spreken. Hij ligt nu in een gevaarlijke toestand tussen slaap en dood, verstrikt in een web van nachtmerries. De essentie die je me gaf is zwaar besmet, maar we hebben een kans om hem te bereiken.$B$BReis ver naar de ijzige landen van oostelijk Winterspring en zoek een van onze sterfelijke bondgenoten: Umbranse the Spiritspeaker. Hij is een menselijk medium dat voor de doden spreekt. Eranikus is niet echt dood, maar Umbranse kan ons misschien toch helpen.",
  o = "Reis naar het oosten van Winterspring en spreek met Umbranse the Spiritspeaker.",
  c = "Itharius deed er wijs aan je naar mij te sturen. Eranikus is niet dood zoals jij de dood begrijpt, maar hij zal ons binnenkort met zijn eigen woorden raad geven. Voorlopig kan ik je echter niet direct helpen... in elk geval nog niet.$b$bIk leen je mijn vaardigheid in het spreken met de doden, maar eerst heb ik de hulp nodig van iemand die, anders dan ik, niet beperkt wordt door de zwakte van de ouderdom. Mijn krachtigste voorspellingsinstrument is tegen mijn wil van me afgepakt. Zonder dat instrument kunnen we Eranikus niet helpen.",
  g = { {"bedenken", "to devise, think up"}, {"toestand", "state"}, {"verstrikt", "tangled, twisted"}, {"besmet", "tainted, infected"}, {"ijzige", "icy (ijzig)"}, {"sterfelijke", "mortal (sterfelijk)"}, {"bondgenoten", "allies (bondgenoot)"}, {"medium", "medium (spirit speaker)"}, {"deed er wijs aan", "was wise to"}, {"raad", "advice"}, {"Voorlopig", "for now"}, {"beperkt", "limited (beperken)"}, {"zwakte", "frailty, weakness"}, {"ouderdom", "old age"}, {"voorspellingsinstrument", "augury device"} },
},

[5141] = { en = "Dragonscale Leatherworking", tier = 4,
  t = "Dragonscale Leatherworking",
  d = "Dragonscale Leatherworking is niet makkelijk, maar het levert heel veel op. Ik leer je hoe je dit fijne maliënpantser maakt, maar alleen als je akkoord gaat met bepaalde voorwaarden.$B$BAls je dit pad kiest, beloof je dat je nooit Elemental of Tribal Leatherworking leert; aan de top van het vak is er maar plaats voor één van de drie. Verder wil ik een paar voorbeelden van je beste werk met scorpid-pantser zien. Tot slot wil ik bewijs dat je het basismateriaal van het vak kunt krijgen: de schubben van het drakenvolk.",
  o = "Breng 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves en 10 Worn Dragonscales naar Peter Galen in Azshara.$B$BMet deze opdracht krijg je toegang tot de kunst van Dragonscale Leatherworking.$B$BAls je deze opdracht voltooit, kun je Elemental Leatherworking en Tribal Leatherworking niet meer leren; zorg dat dit het pad is dat je wilt volgen voordat je dat doet.",
  p = "Als je klaar bent voor een blijvende beslissing en Dragonscale-leerbewerker wilt worden, dan neem ik je graag aan als leerling. Breng me gewoon de dingen waar ik om vroeg, dan beginnen we met je opleiding.",
  c = "Dat moet ik je nageven: er is een sterke wil voor nodig om zo'n blijvende beslissing te nemen als jij net hebt gedaan. Ik verzeker je dat Dragonscale Leatherworking een winstgevend en lonend pad voor je zal blijken.$B$BWil je later verder trainen in deze kunst, spreek me dan gewoon aan. Dan geef ik je alle kennis die je nog niet hebt geleerd.",
  g = { {"levert heel veel op", "is extremely rewarding (opleveren)"}, {"maliënpantser", "mail armor"}, {"voorwaarden", "conditions (voorwaarde)"}, {"vak", "craft, trade"}, {"voorbeelden", "samples (voorbeeld)"}, {"basismateriaal", "staple material"}, {"schubben", "scales (schub)"}, {"drakenvolk", "dragonkin"}, {"voltooit", "complete (voltooien)"}, {"blijvende", "permanent (blijvend)"}, {"leerbewerker", "leatherworker"}, {"nageven", "to grant, give credit"}, {"verzeker", "assure (verzekeren)"}, {"winstgevend", "profitable"}, {"lonend", "rewarding"} },
},

[5143] = { en = "Tribal Leatherworking", tier = 4,
  t = "Tribal Leatherworking",
  d = "Om Tribal Leatherworking te leren, moet je begrijpen hoe oorspronkelijk de natuur echt is. Ik weet dat je de kunst van pantser van wild leather al beheerst, en ik wil je opleiding graag afmaken.$B$BWeet dit, $c: als je dit pad kiest, beloof je dat je nooit Dragonscale of Elemental Leatherworking leert; er is maar plaats voor één van de drie kunsten. Breng me verder de beste voorbeelden van je pantser van wild leather. Vanaf daar beginnen we aan je meesterschap.",
  o = "Breng een Wild Leather Vest en een Wild Leather Helmet naar Caryssia Moonhunter in Feralas.$B$BMet deze opdracht krijg je toegang tot de kunst van Tribal Leatherworking.$B$BAls je deze opdracht voltooit, kun je Dragonscale Leatherworking en Elemental Leatherworking niet meer leren; zorg dat dit het pad is dat je wilt volgen voordat je dat doet.",
  p = "De natuur is een kracht die je tevreden moet stellen voordat je kunt hopen te leren hoe je haar wil in je leren kledingstukken buigt. Breng me je offer aan deze kracht, en ik zorg ervoor dat je gehoord wordt.",
  c = "Je hebt je beste offers gegeven, en de natuur laat je haar binnenkort naar je wil buigen. Zodra ik mijn lessen heb afgerond, wordt je werk zelf een natuurkracht.$B$BWil je later verder trainen in deze kunst, spreek me dan gewoon aan. Dan geef ik je alle kennis die je nog niet hebt geleerd.",
  g = { {"oorspronkelijk", "primal, original"}, {"beheerst", "have mastered (beheersen)"}, {"afmaken", "to finish, complete"}, {"meesterschap", "mastery"}, {"voltooit", "complete (voltooien)"}, {"tevreden moet stellen", "must appease (tevredenstellen)"}, {"kledingstukken", "garments (kledingstuk)"}, {"buigt", "bend (buigen)"}, {"offer", "offering, sacrifice"}, {"afgerond", "finished (afronden)"}, {"natuurkracht", "force of nature"} },
},

[5144] = { en = "Elemental Leatherworking", tier = 4,
  t = "Elemental Leatherworking",
  d = "Elemental Leatherworking is wat ik ken. Als je bereid bent je geest te openen voor de grotere krachten van de materie, deel ik alles met je wat er te leren valt.$B$BWeet dit, $c: als je dit pad kiest, beloof je dat je nooit Dragonscale of Tribal Leatherworking leert; er is maar plaats voor één van de drie kunsten. Verder wil ik goed bewijs dat je in harmonie bent met de elementen van de natuur. Breng me daarom de zuiverste essenties van vuur, water, aarde en wind.",
  o = "Breng 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth en 2 Breath of Wind naar Sarah Tanner in Searing Gorge.$B$BMet deze opdracht krijg je toegang tot de kunst van Elemental Leatherworking.$B$BAls je deze opdracht voltooit, kun je Dragonscale Leatherworking en Tribal Leatherworking niet meer leren; zorg dat dit het pad is dat je wilt volgen voordat je dat doet.",
  p = "Dit soort pantser van leer maken vraagt geduld en toewijding. Als je je lot eenmaal aan de elementen hebt verbonden, kun je ze nooit meer de rug toekeren. Breng me bewijs dat je het waard bent, dan beginnen we.",
  c = "Je hebt je lot verbonden, en de elementen aanvaarden je. Zodra ik mijn lessen heb afgerond, zul je de wil hebben om de beste leren kleding te maken.$B$BWil je later verder trainen in deze kunst, spreek me dan gewoon aan. Dan geef ik je alle kennis die je nog niet hebt geleerd.",
  g = { {"bereid", "willing"}, {"materie", "substance, matter"}, {"in harmonie", "in tune"}, {"zuiverste", "purest (zuiver)"}, {"essenties", "essences (essentie)"}, {"geduld", "patience"}, {"toewijding", "dedication"}, {"je lot verbonden", "cast your lot (verbinden)"}, {"de rug toekeren", "to turn your back on"}, {"aanvaarden", "accept"}, {"afgerond", "finished (afronden)"} },
},

