  t = "Grootmeester van de Arena",
  p = "Halt, landrot! Breng me 12 sieraden van de Arena Master, dan word je Grootmeester van de Gurubashi Arena! Arrrr!",
  c = "Veel bloed heb je op de vloer van de Arena vergoten, en ik ben blij dat ik je Grootmeester van de Arena mag noemen!",
