[8461] = { en = "Deadwood of the North", tier = 4,
  t = "De Deadwood in het noorden",
  d = "Recht ten zuidwesten van ons ligt een kamp van Deadwood-furbolgs. Het kamp is doordrenkt van verdorvenheid, en ik wil daar een einde aan maken voordat ze een probleem worden.$B$BDe Deadwood-stam is kwaadaardig, maar dat komt door de fel die hun geest vervuilt. Hun vijandigheid is niet echt aangeboren, maar toch kunnen we ze niet helpen. Het maakt me verdrietig dat we tegen onze eigen broeders moeten vechten.$B$BAlsjeblieft, $N, ik vraag je te doen wat er gedaan moet worden. Bespaar me alleen de details; zulke nare beelden maken me veel te veel van streek.",
  o = "Nafien wil dat je 6 Deadwood Den Watchers, 6 Deadwood Avengers en 6 Deadwood Shamans doodt. Ga terug naar hem in het noorden van Felwood, bij de ingang van Timbermaw Hold.",
  p = "Zodra je het vertrouwen van de Timbermaw wint, weet ik zeker dat we iets voor je kunnen doen. De Timbermaw vergeten hun bondgenoten niet, vooral niet in duistere tijden zoals deze.",
  c = "Ik voel dat je hebt gewonnen. Overwinning... zo'n leeg woord, als je bedenkt wat er moest gebeuren. Hoe dan ook, je hebt bewezen dat je ons vertrouwen waard bent.$B$BHet kan even duren voordat de Timbermaw je zonder vijandigheid in de Hold verwelkomen. Toch zal je doorzettingsvermogen elk wantrouwen van mijn broeders over jou langzaam wegnemen. Zolang je ons nooit verraadt en nooit wapens tegen ons opheft, vinden we een gemeenschappelijke basis.",
  g = { {"doordrenkt", "permeated, soaked"}, {"verdorvenheid", "corruption"}, {"stam", "tribe"}, {"kwaadaardig", "evil"}, {"vervuilt", "pollutes (vervuilen)"}, {"vijandigheid", "hostility"}, {"aangeboren", "innate"}, {"broeders", "brethren (broeder)"}, {"Bespaar", "spare (besparen)"}, {"van streek", "upset"}, {"vertrouwen", "trust"}, {"Overwinning", "victory"}, {"doorzettingsvermogen", "perseverance"}, {"wantrouwen", "suspicion, distrust"}, {"verraadt", "betray (verraden)"} },
},

[6241] = { en = "Winterfall Activity", tier = 4,
  t = "Activiteit van de Winterfall",
  d = "De Timbermaw blijven graag op zichzelf, $N. We laten mensen die hebben bewezen dat ze te vertrouwen zijn veilig door, maar andere furbolg-stammen proberen we zo veel mogelijk te vermijden.$B$BDe laatste tijd merk ik dat de Winterfall-stam steeds vijandiger tegen ons wordt. Ze lijken in een woedende toestand te zijn, helemaal verteerd door hun eigen angst en haat voor alles wat ze niet begrijpen.$B$BAls je hun aantal kunt verminderen, helpt ons dat enorm, $N.",
  o = "Salfa wil dat je 6 Winterfall Totemics, 6 Winterfall Den Watchers en 6 Winterfall Pathfinders doodt.",
  p = "We waarderen heel erg wat je voor de Timbermaw hebt gedaan, $N. Als je zo doorgaat, verdien je zeker het vertrouwen en respect van mijn stam.",
  c = "Bedankt voor wat je hebt gedaan. Help ons alsjeblieft verder, $N. We hebben maar heel weinig bondgenoten op wie we kunnen rekenen.",
  g = { {"op zichzelf", "to themselves"}, {"vermijden", "to avoid"}, {"vijandiger", "more hostile (vijandig)"}, {"woedende", "raging (woedend)"}, {"verteerd", "consumed, engulfed (verteren)"}, {"haat", "hatred"}, {"waarderen", "appreciate"}, {"verdien", "earn (verdienen)"}, {"bondgenoten", "allies (bondgenoot)"}, {"rekenen", "to count, call upon"}, {"verminderen", "to reduce"} },
},

[8464] = { en = "Winterfall Activity", tier = 4,
  t = "Activiteit van de Winterfall",
  d = "De Timbermaw blijven graag op zichzelf, $N. We laten mensen die we vertrouwen veilig door, maar andere furbolg-stammen proberen we zo veel mogelijk te vermijden.$B$BDe laatste tijd wordt de Winterfall-stam steeds vijandiger tegen ons. Ze lijken in een woedende toestand te zijn, helemaal verteerd door hun eigen angst en haat voor alles wat ze niet begrijpen.$B$BIk moet je vragen hun aantal uit te dunnen, zodat de dreiging tegen ons kleiner wordt. Zoek ze op in Winterfall Village, ver ten oosten van hier.",
  o = "Salfa wil dat je 8 Winterfall Shaman, 8 Winterfall Den Watchers en 8 Winterfall Ursa doodt. Salfa staat vlak buiten de ingang van Timbermaw Hold in Winterspring.$b",
  p = "We waarderen heel erg wat je voor de Timbermaw hebt gedaan, $N. Als je zo doorgaat, verdien je zeker het vertrouwen en respect van mijn stam.",
  c = "Bedankt voor wat je hebt gedaan, hoe triest het ook is. Neem dit aan als teken van dank.$B$BIk wil je vragen ons alsjeblieft te blijven helpen, $N. We hebben maar heel weinig bondgenoten op wie we kunnen rekenen. Zonder jouw hulp zouden de dreigingen tegen mijn stam vast te groot zijn om alleen aan te kunnen.",
  g = { {"op zichzelf", "to themselves"}, {"vermijden", "to avoid"}, {"vijandiger", "more hostile (vijandig)"}, {"woedende", "raging (woedend)"}, {"verteerd", "consumed, engulfed (verteren)"}, {"haat", "hatred"}, {"waarderen", "appreciate"}, {"verdien", "earn (verdienen)"}, {"bondgenoten", "allies (bondgenoot)"}, {"rekenen", "to count, call upon"}, {"uit te dunnen", "to thin out (uitdunnen)"}, {"dreiging", "threat"}, {"triest", "sad"}, {"teken van dank", "token of thanks"}, {"aan te kunnen", "to handle (aankunnen)"} },
},

[7899] = { en = "Small Furry Paws", tier = 4,
  t = "Kleine harige poten",
  p = "De eerste les om een menigte te trekken: lok ze met snufjes en prulletjes! Kun je me helpen?$B$BIk heb Small Furry Paws nodig als prijzen. Die vind je bij de katten van de Barrens of Darkshore....$B$BBreng me wat poten, dan ruil ik ze voor een Darkmoon Faire-ticket.",
  c = "Geweldig, je hebt ze! Hier kunnen we speelgoed en snuisterijen van maken, en die trekken meer mensen naar de Faire!$B$BHier is je ticket, $N. Je hebt het verdiend!",
