[7900] = { en = "Torn Bear Pelts", tier = 4,
  t = "Gescheurde berenvachten",
  p = "Kinderen houden van speelgoed! En van welk ras ze ook zijn, ik heb gemerkt dat alle kinderen dol zijn op zacht, pluizig speelgoed van Torn Bear Pelts!$B$BDie vachten kun je krijgen van de beren van Ashenvale of Hillsbrad. Breng me er een hoop van, en verdien zelf een hoop Darkmoon Faire-tickets!",
  c = "Mooie vachten, $N! Ik laat iemand er een stel knuffels van naaien. Met wat vulling en een beetje verf zijn kinderen in heel Azeroth er straks jaloers op, denk ik!$B$BTickets? O ja, je betaling! Hier zijn ze!",
  g = { {"ras", "race"}, {"gemerkt", "noticed (merken)"}, {"dol zijn op", "to love, be crazy about"}, {"pluizig", "fluffy, plush"}, {"vachten", "pelts (vacht)"}, {"een hoop", "a heap, a lot"}, {"knuffels", "plush toys (knuffel)"}, {"naaien", "to sew"}, {"vulling", "stuffing"}, {"jaloers", "envious, jealous"}, {"betaling", "payment"} },
},

[7901] = { en = "Soft Bushy Tails", tier = 4,
  t = "Zachte borstelige staarten",
  p = "Het is verbazend wat mensen waardevol vinden! Neem bijvoorbeeld een houten stok met een zachte, borstelige staart eraan. Jij en ik denken misschien dat zoiets niet zo veel waard is... maar als je dat stuk rommel een leuke naam geeft, zoals \"Savage Fuzz Tail\", en het in een mooi doosje stopt, dan denken mensen dat het waardevol is. Afval wordt een schat!$B$BHaal Soft Bushy Tails voor me bij de wolven van Desolace en de Badlands, dan geef ik je Darkmoon Faire-tickets.",
  c = "Goed gedaan, $N! Deze staarten worden geweldige prijzen voor onze bezoekers, en dat betekent blije bezoekers... die met hun vrienden praten en meer bezoekers meebrengen!$B$BHier zijn je tickets! Veel plezier op de Darkmoon Faire... en vergeet niet je vrienden over ons te vertellen!",
  g = { {"verbazend", "amazing"}, {"waardevol", "valuable"}, {"bijvoorbeeld", "for instance"}, {"borstelige", "bushy (borstelig)"}, {"staart", "tail"}, {"rommel", "junk"}, {"doosje", "little box (doos)"}, {"Afval", "trash, rubbish"}, {"schat", "treasure"}, {"bezoekers", "visitors (bezoeker)"}, {"meebrengen", "to bring along"} },
},

[7902] = { en = "Vibrant Plumes", tier = 4,
  t = "Felgekleurde veren",
  p = "De verbeelding van een mens is iets ongelooflijks. Ze kan de kleinste heuvel laten lijken op de grootste berg. Ze kan de meest onschuldige schaduw laten lijken alsof een vreselijke nachtmerrie hem werpt!$B$BWij van de Darkmoon Faire laten de verbeelding van onze bezoekers opbloeien! Maar om hun verbeelding wat op te rekken... moeten we soms een beetje sluw zijn.$B$BIk heb Vibrant Plumes nodig voor een van mijn attracties. Je kunt ze krijgen van de vogels in de gevaarlijkere gebieden van Azeroth. Breng me de veren, dan worden veel tickets van jou!",
  c = "Ah, de veren! Ze zijn prachtig, vind je niet? Met zulke schoonheden is het makkelijk om iemands verbeelding aan te wakkeren!$B$BJe doet zulk liefdadig werk, $N. De glimlach op het gezicht van onze bezoekers als ze de show zien, is al een prachtige beloning, maar neem alsjeblieft ook deze tickets aan.",
  g = { {"verbeelding", "imagination"}, {"ongelooflijks", "incredible (ongelooflijk)"}, {"heuvel", "hill"}, {"onschuldige", "innocuous, harmless (onschuldig)"}, {"werpt", "casts (werpen)"}, {"opbloeien", "to blossom"}, {"op te rekken", "to stretch (oprekken)"}, {"sluw", "tricky, cunning"}, {"gebieden", "areas (gebied)"}, {"schoonheden", "beauties (schoonheid)"}, {"aan te wakkeren", "to spark, kindle (aanwakkeren)"}, {"liefdadig", "charitable"}, {"beloning", "reward, payment"} },
},

[7903] = { en = "Evil Bat Eyes", tier = 4,
  t = "Kwaadaardige vleermuisogen",
  p = "Dwaal je weleens laat in de nacht door een grot, op zoek naar avontuur? Ja? Echt waar? Nou, dan heb je vast de griezelige ogen van vleermuizen gezien. Ze staren je van hoog aan en wachten tot je even niet oplet, zodat ze je bloed kunnen zuigen!$B$BEng idee, vind je niet? Natuurlijk! Vleermuisogen zijn ongetwijfeld eng!$B$BWil je wat Evil Bat Eyes voor me halen, $N? Ik wil ze voor... iets wat ik aan het ontwerpen ben. Iets engs.$B$BJe kunt ze krijgen van de vleermuizen in de Eastern Plaguelands.",
  c = "Geweldig! Je hebt de ogen! Ik hoop dat de jacht op die vleermuizen eng voor je was. Want als een dappere $c zoals jij ervan schrok, dan maken die ogen onze bezoekers van de Faire zeker bang.$B$BNeem deze tickets, $N, en bedankt voor je diensten.",
  g = { {"Dwaal", "wander (dwalen)"}, {"weleens", "ever, sometimes"}, {"griezelige", "creepy (griezelig)"}, {"vleermuizen", "bats (vleermuis)"}, {"staren", "to stare"}, {"oplet", "pay attention (opletten)"}, {"zuigen", "to suck"}, {"Eng", "scary"}, {"ongetwijfeld", "no doubt, undoubtedly"}, {"ontwerpen", "to design"}, {"jacht", "hunt"}, {"schrok", "got scared (schrikken)"}, {"diensten", "services (dienst)"} },
},

