[7937] = { en = "Your Fortune Awaits You...", tier = 4,
  t = "Je fortuin wacht op je...",
  d = "\"Je fortuin wacht op je in Eastvale.\"$B$BDe voorspelling die Sayge je gaf, voelt een beetje warm aan. Als je hem stevig vastpakt, zie je een beeld van het Eastvale Logging Camp in Elwynn Forest. Als je beter naar het beeld kijkt, zie je een hooiberg die naast een stal staat.$b",
  o = "Reis naar het Eastvale Logging Camp in Elwynn Forest en zoek je fortuin.",
  p = "Deze hooiberg lijkt op die uit je visioen.",
  c = "Als je snel in de hooiberg zoekt, vind je er een afgesloten kistje in! Het lijkt erop dat je je fortuin hebt gevonden!",
  g = { {"fortuin", "fortune"}, {"voorspelling", "fortune, prediction"}, {"vastpakt", "grasp (vastpakken)"}, {"beeld", "image"}, {"visioen", "vision"}, {"afgesloten kistje", "lockbox"}, {"stevig", "firmly"}, {"hooiberg", "haystack"}, {"stal", "stable"} },
},

[7938] = { en = "Your Fortune Awaits You...", tier = 4,
  t = "Je fortuin wacht op je...",
  d = "\"Je fortuin wacht op je in de Deadmines.\"$B$BDe voorspelling die Sayge je gaf, voelt een beetje warm aan. Als je hem stevig vastpakt, zie je een beeld van de Deadmines in Moonbrook, het verwoeste gehucht van Westfall. Als je beter naar het beeld kijkt, kronkel je door bochtige gangen tot je bij een glinsterend portaal komt... een portaal dat naar het hart van de mijnen zelf leidt. Als je erdoorheen stapt, verschijnt er uit het niets een vreemde kist.",
  o = "Reis naar de Deadmines in Westfall en zoek je fortuin.",
  p = "Deze kist lijkt op die uit je visioen...",
  c = "Als je snel in de kist zoekt, vind je er een afgesloten kistje in! Het lijkt erop dat je je fortuin hebt gevonden!",
  g = { {"fortuin", "fortune"}, {"voorspelling", "fortune, prediction"}, {"vastpakt", "grasp (vastpakken)"}, {"beeld", "image"}, {"visioen", "vision"}, {"afgesloten kistje", "lockbox"}, {"kronkel", "wind, twist (kronkelen)"}, {"bochtige", "twisty (bochtig)"}, {"glinsterend", "shimmering"}, {"portaal", "portal"}, {"uit het niets", "out of nowhere"}, {"verwoeste", "ruined (verwoest)"}, {"gehucht", "hamlet"}, {"mijnen", "mines (mijn)"} },
},

