[8222] = { en = "Glowing Scorpid Blood", tier = 4,
  t = "Gloeiend schorpioenbloed",
  p = "In al mijn tijd op de Faire heb ik veel over klanten geleerd. Hier is een van die pareltjes van wijsheid: klanten houden van spullen die gloeien! Het maakt niet uit wat het is. Je kunt een gebroken stoelpoot laten gloeien, en elk kind komt van kilometers ver om er een te halen!$B$BDus, $N, ik heb Glowing Scorpid Blood nodig. Je vindt het bij de schorpioenen van Silithus, de Blasted Lands of de Burning Steppes.",
  c = "Goed werk, $N! Heel erg bedankt! Ik ga verf maken van dit bloed en allerlei goedkope rommel in gloeiende schatten veranderen!$B$BHier zijn je tickets, en nogmaals bedankt!",
  g = { {"klanten", "customers (klant)"}, {"pareltjes van wijsheid", "nuggets of wisdom"}, {"spullen", "stuff, things"}, {"gloeien", "to glow"}, {"Het maakt niet uit", "It doesn't matter"}, {"stoelpoot", "chair leg"}, {"schorpioenen", "scorpids, scorpions (schorpioen)"}, {"verf", "paint"}, {"allerlei", "all kinds of"}, {"goedkope", "cheap (goedkoop)"}, {"schatten", "treasures (schat)"} },
},

[8223] = { en = "More Glowing Scorpid Blood", tier = 4,
  t = "Meer gloeiend schorpioenbloed",
  p = "Dat schorpioenbloed werkt geweldig, $N! Het is verbazend hoe een beetje glitter en glans een gewilde snuisterij kan maken van iets wat anders gewoon rommel is. De klanten zijn er dol op, en liefde is waar het allemaal om draait, vind je niet...$B$BJe hebt me erg geholpen, $N. Ik heb niet echt meer Glowing Scorpid Blood nodig, maar als je me meer brengt, ruil ik toch wat tickets met je.",
  c = "Nogmaals bedankt, $N. Hier zijn je tickets!",
